import{lanes,tracks,drops,mixes,defaults}from'./data.js';import{read,write}from'./storage.js';import*as player from'./player.js';import{loadWeeklyFeed,feedState}from'./feed.js';
const heroStyles=document.createElement('link');heroStyles.rel='stylesheet';heroStyles.href='/hero.css';document.head.append(heroStyles);
const $=s=>document.querySelector(s);let interactions=read('interactions',{}),profiles=read('profiles',{base:{...defaults},weekly:null}),layout=read('layout',[{id:'start',size:'standard'},{id:'signal',size:'compact'},{id:'lane0',size:'wide'},{id:'lane1',size:'wide'},{id:'lane2',size:'wide'},{id:'lane3',size:'standard'},{id:'mix',size:'standard'}]);let editing=false,filter='all',detailId=null,tunerScope='base',draft={},dragged=null;const defaultLayout=JSON.parse(JSON.stringify([{id:'start',size:'standard'},{id:'signal',size:'compact'},{id:'lane0',size:'wide'},{id:'lane1',size:'wide'},{id:'lane2',size:'wide'},{id:'lane3',size:'standard'},{id:'mix',size:'standard'}]));
let heroFrame=null,heroObserver=null,heroCleanup=null;
function heroMarkup(){return `<section class="ascii-hero" aria-label="DROP:PORTAL signal visual"><canvas id="ascii-hero-canvas" role="img" aria-label="Full-width cyan ASCII texture with evolving rotational flow"></canvas><div class="ascii-hero-chrome" aria-hidden="true"><span>LIVE SIGNAL / 001</span><i></i><span>DROP:PORTAL</span></div><noscript><img src="/ascii-portal.png" alt="Cyan ASCII portal graphic"></noscript></section>`}
function stopHero(){if(heroFrame!==null)cancelAnimationFrame(heroFrame);heroFrame=null;heroObserver?.disconnect();heroObserver=null;heroCleanup?.();heroCleanup=null}
function initHero(){
  stopHero();const canvas=$('#ascii-hero-canvas');if(!canvas)return;
  const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)return;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  let width=0,height=0,ratio=1,visible=true,last=0,elapsed=0;
  // Preserve the full-width ASCII field; rotate its sampled contours, not the canvas.
  const lobes=[[-.86,.15,.39,.31,0],[-.39,-.48,.48,.23,2.1],[.07,.42,.42,.28,4.7],[.48,-.31,.47,.19,1.3],[.94,.36,.38,.26,3.4]];
  function draw(t){
    ctx.setTransform(ratio,0,0,ratio,0,0);ctx.fillStyle='#030607';ctx.fillRect(0,0,width,height);
    const cell=6,row=8,cols=Math.ceil(width/cell),rows=Math.ceil(height/row);
    ctx.font='8px monospace';ctx.textBaseline='middle';ctx.textAlign='center';
    const shapes=lobes.map(([x,y,r,s,p])=>({x:x+Math.sin(t*s+p)*.035,y:y+Math.cos(t*s*.71+p)*.09,r:r*(1+.09*Math.sin(t*s*.63+p)),p,s}));
    for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){
      const u=(i*cell/width*2-1)*1.2,v=(j*row/height*2-1)*.7;
      // Gentle vortex advection with differential rotation across the field.
      const radius=Math.hypot(u,v),turn=t*(.085+.035*Math.exp(-radius*radius));
      const x=u*Math.cos(turn)+v*Math.sin(turn),y=-u*Math.sin(turn)+v*Math.cos(turn);
      let field=0;
      for(const l of shapes){const dx=x-l.x,dy=y-l.y;const angle=Math.atan2(dy,dx);const r=l.r*(1+.10*Math.sin(angle*3-t*l.s+l.p)+.05*Math.cos(angle*5-t*l.s*.6));field+=Math.exp(-(dx*dx+dy*dy)/(r*r)*2.5);}
      field+=.035*Math.sin(x*8+y*5+t*.17)*Math.cos(y*7-x*3-t*.13);
      const band=field*8,edge=Math.pow((Math.cos(band*Math.PI*2)+1)/2,6);
      const mask=Math.min(1,Math.max(0,(field-.07)*9));
      if(mask<.02)continue;
      const phase=Math.sin(x*5-y*4+t*.29),density=Math.min(1,field*.6);
      let char=edge>.65?'=':edge>.25?'+':density>.52?'#':density>.25?':':'.';
      if(edge<.25&&phase>.45)char='|';
      const a=mask*(.19+edge*.62+density*.15);
      ctx.fillStyle=`rgba(76,222,244,${Math.min(.95,a)})`;ctx.fillText(char,i*cell+3,j*row+4);
    }
  }
  function size(){const box=canvas.getBoundingClientRect();width=Math.max(1,box.width);height=Math.max(1,box.height);ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);draw(elapsed);}
  function tick(now){heroFrame=null;if(!visible||document.hidden||reduced.matches)return;if(!last)last=now;if(now-last>=1000/24){elapsed+=Math.min(now-last,80)/1000;last=now;draw(elapsed);}heroFrame=requestAnimationFrame(tick);}
  function sync(){if(heroFrame!==null)cancelAnimationFrame(heroFrame);heroFrame=null;last=0;if(visible&&!document.hidden&&!reduced.matches)heroFrame=requestAnimationFrame(tick);else draw(elapsed);}
  const intersection=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync()});intersection.observe(canvas);
  heroObserver=new ResizeObserver(size);heroObserver.observe(canvas);size();
  document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',sync);
  heroCleanup=()=>{intersection.disconnect();document.removeEventListener('visibilitychange',sync);reduced.removeEventListener('change',sync)};sync();
}
function persist(k,v){if(!write(k,v))toast('Your browser could not save these changes.')}function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function activeProfile(){return profiles.weekly?.week===drops[0].id?profiles.weekly:profiles.base}function act(id,key){interactions[id]??={};interactions[id][key]=!interactions[id][key];interactions[id].updatedAt=Date.now();persist('interactions',interactions);render();if(detailId)detail(detailId,false);toast(key==='hidden'?'Track hidden · restore from this drop’s footer':key==='saved'?(interactions[id].saved?'Saved to your crate':'Removed from saved'):(interactions[id].heard?'Marked as heard':'Marked as unheard'))}
const buttons=t=>`<div class="actions"><button data-action="saved" data-id="${t.id}" class="${interactions[t.id]?.saved?'active':''}" aria-pressed="${!!interactions[t.id]?.saved}" aria-label="${interactions[t.id]?.saved?'Unsave':'Save'} ${t.title}">${interactions[t.id]?.saved?'▣ Saved':'⊞ Save'}</button><button data-action="heard" data-id="${t.id}" class="${interactions[t.id]?.heard?'active':''}" aria-pressed="${!!interactions[t.id]?.heard}">✓ Heard</button></div>`;
const playButton=t=>t.preview?`<button class="play" data-play="${t.id}" aria-label="Play ${t.title}">▶</button>`:'<span class="no-preview">NO PREVIEW</span>';
function card(t){return `<article class="track"><div class="track-top"><button class="identity" data-detail="${t.id}"><span class="artist">${t.artistName}</span><h3>${t.title}</h3></button><div class="score">${t.score}<small>/ 100</small></div></div><span class="track-meta">${t.bpm} BPM · ${t.confidence}% CONFIDENCE</span><p class="reason">${t.reason}</p><div class="track-bottom">${playButton(t)}${buttons(t)}</div></article>`}
function priority(t,i){return `<article class="priority-row"><span class="rank">0${i+1}</span>${playButton(t)}<button class="identity" data-detail="${t.id}"><strong>${t.title}</strong><span class="artist">${t.artistName} · ${lanes[t.lane].split(' / ')[0]}</span></button><div class="score">${t.score}<small>${t.confidence}% CONF.</small></div><p class="reason">${t.reason}</p></article>`}
function meter(label,value,desc){return `<div class="meter"><label>${label}<b>${desc??value+'%'}</b></label><div class="bar"><i style="width:${value}%"></i></div></div>`}
function module(m,ts){let title='',body='',cls='',sub='';if(m.id==='start'){title='<span class="cyan">↗</span> &nbsp; Start here';sub='YOUR FIRST THREE';cls='priority';body=`<div class="panel-body">${ts.slice(0,3).map(priority).join('')||'<p>No visible tracks. Restore hidden tracks below.</p>'}</div>`}else if(m.id==='signal'){title='Weekly signal';sub='THE SHAPE OF THIS DROP';cls='signal-panel';const p=activeProfile();let counts=lanes.map((_,i)=>ts.filter(t=>t.lane===i).length);body=`<div class="signal"><div class="stats"><div><strong>${String(ts.length).padStart(2,'0')}</strong><span>TRACKS SELECTED</span></div><div><strong>${p.mixes?'01':'00'}</strong><span>DJ MIXES</span></div></div><div class="distribution">${counts.map(c=>`<span style="flex:${c}"></span>`).join('')}</div><div class="lane-key">${counts.slice(0,3).map((c,i)=>`<span>${['■','□','▧'][i]} ${['Future','Deep','Jungle'][i]} ${c}</span>`).join('')}</div>${meter('Discovery depth',p.depth,p.depth>65?'Deep dig':'Familiar ground')}${meter('Experimental bias',p.experimental)}${meter('Floor ↔ headphones',p.floor,p.floor+'% headphones')}<p class="signal-foot">Your local profile · ${profiles.weekly?.week===drops[0].id?'This week override':'Base preferences'}</p></div>`}else if(m.id==='mix'){if(!activeProfile().mixes)return '';title='DJ mix crate';sub='01 SESSION';body=`<div class="mix"><div class="mix-icon">◉</div><div><span class="artist">${mixes[0].artistName}</span><strong>${mixes[0].title}</strong><span class="track-meta">Demo entry · listening link not supplied</span></div>${buttons(mixes[0])}</div>`}else{let i=Number(m.id.slice(-1));let list=ts.filter(t=>t.lane===i);if(!list.length)return '';title=`<span class="marker m${i}"></span>${lanes[i]}`;sub=String(list.length).padStart(2,'0')+' TRACKS';body=`<div class="bin-grid">${list.map(card).join('')}</div>`}const sizes=m.id==='signal'?['compact','standard']:m.id==='start'||m.id==='mix'?['standard','wide']:['wide'];return `<section class="panel ${m.size} ${cls}" data-module="${m.id}">${editing?`<div class="module-controls"><button draggable="true" data-drag="${m.id}" aria-label="Drag ${m.id} module">⠿ Move</button><button data-move="-1" data-module-id="${m.id}" aria-label="Move ${m.id} up">↑</button><button data-move="1" data-module-id="${m.id}" aria-label="Move ${m.id} down">↓</button><label>Size <select data-size="${m.id}">${sizes.map(s=>`<option ${s===m.size?'selected':''}>${s}</option>`).join('')}</select></label></div>`:''}<div class="panel-head"><h2>${title}</h2><small>${sub}</small></div>${body}</section>`}
function header(title,sub,drop){const live=feedState.source==='github';return `<div class="drop-heading"><div><div class="eyebrow">${drop?'WEEKLY TRANSMISSION / '+drop.period:'YOUR PERSONAL CRATE'}</div><h1>${title}</h1><p>${sub}</p></div><span class="seed">${live?'LIVE FEED · GITHUB':'PHASE 1 · DEMO FALLBACK'}</span></div>`}
function render(){let path=location.pathname.replace(/\/$/,'')||'/';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route==='/'?path==='/':path.startsWith(a.dataset.route)));$('#saved-count').textContent=Object.values(interactions).filter(i=>i.saved).length;$('#edit').textContent=editing?'✓ DONE':'⊞ EDIT LAYOUT';$('#edit').hidden=path==='/archive'||path==='/saved';let html='';if(path==='/archive'){html=header('The archive','Previous transmissions. Good music doesn’t expire.')+`<div class="archive-list">${drops.slice(1).map(d=>`<a class="archive-card" href="/archive/${d.id}"><span class="eyebrow">${d.period}</span><h2>Drop ${d.id} <span class="cyan">↗</span></h2><p>${d.ids.length} tracks · Demo collection</p><span class="track-meta">SUB STUDIES / LOOP THEORY / PHASE STUDIES</span></a>`).join('')}</div>`}else if(path==='/saved'){let ts=tracks.filter(t=>interactions[t.id]?.saved&&!interactions[t.id]?.hidden);let ms=mixes.filter(t=>interactions[t.id]?.saved);html=header('Saved for later','Your selections, ready for another listen.')+`<div class="filters">${['all','tracks','mixes'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>`;let items=(filter!=='mixes'?ts.map(card).join(''):'')+(filter!=='tracks'?ms.map(m=>`<article class="track"><span class="artist">${m.artistName}</span><h3>${m.title}</h3><p>${m.reason}</p>${buttons(m)}</article>`).join(''):'');html+=items?`<section class="panel wide"><div class="bin-grid">${items}</div></section>`:'<div class="panel empty"><h2>Your next favorite belongs here.</h2><p>Save a track or mix from This Week to start your crate.</p><a href="/" class="cyan">Explore this week ↗</a></div>'}else{let d=path.startsWith('/archive/')?drops.find(d=>d.id===path.split('/')[2]):drops[0];if(!d){html='<div class="empty"><h1>Drop not found</h1><a href="/archive">Back to archive</a></div>'}else{let ts=d.ids.map(id=>tracks.find(t=>t.id===id)).filter(t=>t&&!interactions[t.id]?.hidden);html=(d===drops[0]?heroMarkup():'')+header(`This week’s drop <span>/ ${d.id}</span>`,'A little further underground. Start with three, dig into the rest.',d)+(editing?'<div class="editbar"><span>Move modules using handles or ↑ ↓. Changes save automatically.</span><button id="reset-layout">Reset layout</button></div>':'')+`<div class="grid ${editing?'editing':''}">${layout.map(m=>module(m,ts)).join('')}</div>`;if(d.ids.some(id=>interactions[id]?.hidden))html+='<p><button id="restore">Restore hidden tracks</button></p>'}}html+=`<p class="footer-note">${feedState.source==='github'?'LIVE WEEKLY FEED · Published recommendations are loaded from the versioned DROP:PORTAL GitHub feed.':'DEMO FALLBACK · Illustrative artists, titles, scores and mixes. Three original synthesized preview studies.'}<br>Preview availability is source-dependent. Preferences and saves stay in this browser.</p>`;$('#app').innerHTML=html;initHero();updatePlayer()}
function route(path){history.pushState({},'',path);editing=false;render();window.scrollTo(0,0)}document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!e.ctrlKey&&!e.metaKey){e.preventDefault();route(a.pathname);return}const b=e.target.closest('button');if(!b)return;if(b.dataset.play){player.play(tracks.find(t=>t.id===b.dataset.play));return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.dataset.action){act(b.dataset.id,b.dataset.action);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.move){move(b.dataset.moduleId,Number(b.dataset.move));return}if(b.dataset.close){$('#'+b.dataset.close).close();if(b.dataset.close==='detail')detailId=null;return}if(b.id==='edit'){editing=!editing;render()}if(b.id==='reset-layout'){layout=JSON.parse(JSON.stringify(defaultLayout));persist('layout',layout);render();toast('Default layout restored')}if(b.id==='restore'){Object.values(interactions).forEach(i=>i.hidden=false);persist('interactions',interactions);render()}if(b.id==='tuner'){tunerScope='base';openTuner()}if(b.dataset.scope){captureDraft();tunerScope=b.dataset.scope;openTuner(false)}if(b.id==='save-tuner'){captureDraft();profiles[tunerScope]=draft[tunerScope];if(tunerScope==='weekly')profiles.weekly.week=drops[0].id;persist('profiles',profiles);$('#tuner-dialog').close();render();toast('Profile saved · applies to future curation')}if(b.id==='clear-week'){profiles.weekly=null;persist('profiles',profiles);$('#tuner-dialog').close();render();toast('This week now uses your base profile')}if(b.id==='dock-close')player.stop()});
function move(id,delta){let i=layout.findIndex(m=>m.id===id),j=i+delta;if(j<0||j>=layout.length)return;[layout[i],layout[j]]=[layout[j],layout[i]];persist('layout',layout);render();toast('Module moved')}
document.addEventListener('change',e=>{if(e.target.dataset.size){layout.find(m=>m.id===e.target.dataset.size).size=e.target.value;persist('layout',layout);render()}});document.addEventListener('dragstart',e=>{let handle=e.target.closest('[data-drag]');if(!editing||!handle)return;dragged=handle.dataset.drag;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move'});document.addEventListener('dragover',e=>{if(editing&&dragged&&e.target.closest('[data-module]'))e.preventDefault()});document.addEventListener('drop',e=>{let target=e.target.closest('[data-module]');if(!editing||!dragged||!target)return;e.preventDefault();let i=layout.findIndex(m=>m.id===dragged),j=layout.findIndex(m=>m.id===target.dataset.module);let[m]=layout.splice(i,1);layout.splice(j,0,m);dragged=null;persist('layout',layout);render()});document.addEventListener('dragend',()=>dragged=null);
function detail(id,show=true){let t=tracks.find(t=>t.id===id);if(!t)return;detailId=id;$('#detail').innerHTML=`<div class="drawer-head"><span>TRACK DETAIL / DEMO</span><button data-close="detail" aria-label="Close track detail">✕</button></div><span class="artist">${t.artistName}</span><h2>${t.title}</h2><span class="track-meta">${lanes[t.lane]} · ${t.bpm} BPM</span><h3>PREVIEW</h3>${t.preview?`<div class="detail-controls">${playButton(t)}<span class="timing" id="detail-time">0:00 / 0:16</span></div><div class="wave" id="detail-wave">Play this study to load its waveform.</div><p class="notice">${t.preview.attribution}</p>`:'<p class="notice">PREVIEW UNAVAILABLE<br>No authorized preview is attached to this demo entry.</p>'}<h3>WHY IT’S HERE</h3><p>${t.reason}</p><h3>ILLUSTRATIVE GRADING</h3>${Object.entries(t.scores).map(([k,v])=>`<div class="metric-row"><span>${k[0].toUpperCase()+k.slice(1)}</span><b>${v} / 100</b></div>`).join('')}<div class="metric-row"><span>Overall / subgenre confidence</span><b>${t.score} / ${t.confidence}%</b></div><h3>RELEASE & SOURCES</h3><p class="notice">Prototype entry. Artist, title and grading are illustrative. Release date, label and purchase links have not been supplied.</p><h3>YOUR CRATE</h3>${buttons(t)}<p><button data-action="hidden" data-id="${t.id}">Hide this track</button></p>`;if(show&&!$('#detail').open)$('#detail').showModal();updatePlayer()}
function openTuner(reset=true){if(reset)draft={base:{...profiles.base},weekly:{...(profiles.weekly?.week===drops[0].id?profiles.weekly:profiles.base)}};let p=draft[tunerScope];$('#tuner-dialog').innerHTML=`<div class="drawer-head"><span>RECOMMENDATION TUNER</span><button data-close="tuner-dialog" aria-label="Close tuner">✕</button></div><h2>Tune your signal.</h2><p>Steer your next discovery session.</p><div class="tuner-tabs"><button data-scope="base" class="${tunerScope==='base'?'active':''}">Base</button><button data-scope="weekly" class="${tunerScope==='weekly'?'active':''}">This week</button></div><p class="notice">Local preferences only. This fixed demo collection will not regenerate.</p>${[['future','Future / Experimental'],['deep','Deep / Minimal / Techy'],['jungle','Jungle / Breaks / Leftfield'],['depth','Discovery depth'],['experimental','Experimental bias'],['floor','Floor → Headphones'],['darkness','Darkness'],['breaks','Break density'],['count','Track count']].map(([k,label])=>`<label class="range-label" for="tune-${k}">${label}<output id="out-${k}">${p[k]}</output></label><input class="range-input" id="tune-${k}" data-pref="${k}" type="range" min="${k==='count'?10:0}" max="${k==='count'?15:100}" value="${p[k]}">`).join('')}<label class="check"><input type="checkbox" id="mixes-enabled" ${p.mixes?'checked':''}>Include DJ mixes</label><button class="primary tuner-save" id="save-tuner">Save ${tunerScope==='base'?'base profile':'this week’s override'}</button>${tunerScope==='weekly'?'<button class="tuner-save" id="clear-week">Use base profile this week</button>':''}`;if(!$('#tuner-dialog').open)$('#tuner-dialog').showModal()}
function captureDraft(){document.querySelectorAll('[data-pref]').forEach(x=>draft[tunerScope][x.dataset.pref]=Number(x.value));draft[tunerScope].mixes=$('#mixes-enabled').checked}document.addEventListener('input',e=>{if(e.target.dataset.pref)$('#out-'+e.target.dataset.pref).textContent=e.target.value;if(e.target.matches('[data-seek]'))player.seek(Number(e.target.value));if(e.target.id==='volume')player.audio.volume=Number(e.target.value)});
function waveHTML(){return player.waveform()+`<input data-seek type="range" min="0" max="${player.audio.duration||16}" step="0.05" value="${player.audio.currentTime}" aria-label="Seek preview">`}
let dockId=null;function updatePlayer(){const t=player.current;document.querySelectorAll('[data-play]').forEach(b=>{const on=t?.id===b.dataset.play&&player.status==='playing';b.textContent=on?'Ⅱ':'▶';b.setAttribute('aria-label',(on?'Pause ':'Play ')+tracks.find(t=>t.id===b.dataset.play)?.title)});$('#dock').hidden=!t;if(!t){dockId=null;return}if(dockId!==t.id){$('#dock').innerHTML=`<div class="dock-inner"><div class="dock-title"><button data-detail="${t.id}"><strong>${t.title}</strong><small>${t.artistName} · ORIGINAL DEMO</small></button></div>${playButton(t)}<div class="wave" id="dock-wave"></div><span class="timing" id="dock-time"></span><input id="volume" class="volume" type="range" min="0" max="1" step=".01" value="${player.audio.volume}" aria-label="Preview volume"><button id="dock-close" aria-label="Stop and close preview">✕</button></div>`;dockId=t.id}const timing=player.status==='error'?'Preview failed · tap play to retry':player.status==='loading'?'Loading…':`${player.time(player.audio.currentTime)} / ${player.time(player.audio.duration||16)}`;$('#dock-time').textContent=timing;updateWave($('#dock-wave'));$('#dock [data-play]').textContent=player.status==='playing'?'Ⅱ':'▶';$('#dock [data-play]').setAttribute('aria-label',(player.status==='playing'?'Pause ':'Play ')+t.title);if(detailId===t.id&&$('#detail-wave')){updateWave($('#detail-wave'));$('#detail-time').textContent=timing}}
function updateWave(el){if(!el)return;const focused=el.contains(document.activeElement);if(focused){const svg=el.querySelector('svg');if(svg){const temp=document.createElement('div');temp.innerHTML=player.waveform();svg.replaceWith(temp.firstElementChild)}}else el.innerHTML=waveHTML()}
window.addEventListener('previewchange',updatePlayer);window.addEventListener('popstate',()=>{editing=false;render()});for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d&&e.clientX<d.getBoundingClientRect().left)d.close()});$('#detail').addEventListener('close',()=>detailId=null);render();loadWeeklyFeed().then(ok=>{if(ok){render();toast('Weekly DROP feed synced')}else render()});
